package pricing;

import java.util.Objects;

public record Customer(String name, CustomerType type, int loyaltyPoints) {

    public Customer {
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(type, "type");
        if (loyaltyPoints < 0) {
            throw new IllegalArgumentException("loyaltyPoints must not be negative: " + loyaltyPoints);
        }
    }
}
package pricing;

public enum CustomerType {
    REGULAR,
    EMPLOYEE
}
package pricing;

import java.math.BigDecimal;

/** Decides which discount rate a customer gets. */
public class DiscountPolicy {
    private static final BigDecimal EMPLOYEE_RATE = new BigDecimal("0.20");
    private static final BigDecimal GOLD_RATE = new BigDecimal("0.15");
    private static final BigDecimal SILVER_RATE = new BigDecimal("0.05");
    private static final int GOLD_POINTS = 2000;
    private static final int SILVER_POINTS = 500;

    public BigDecimal rateFor(Customer customer) {
        return switch (customer.type()) {
            case EMPLOYEE -> EMPLOYEE_RATE;
            case REGULAR -> loyaltyRateFor(customer.loyaltyPoints());
        };
    }

    private BigDecimal loyaltyRateFor(int loyaltyPoints) {
        if (loyaltyPoints >= GOLD_POINTS) {
            return GOLD_RATE;
        }
        if (loyaltyPoints >= SILVER_POINTS) {
            return SILVER_RATE;
        }
        return BigDecimal.ZERO;
    }
}
package pricing;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.math.BigDecimal;
import org.junit.jupiter.api.Test;

class DiscountPolicyTest {
    private final DiscountPolicy policy = new DiscountPolicy();

    @Test
    void regularCustomerWithoutPointsGetsNoDiscount() {
        assertRate("0", new Customer("Ada", CustomerType.REGULAR, 0));
    }

    @Test
    void silverLoyaltyStartsAtFiveHundredPoints() {
        assertRate("0", new Customer("Ada", CustomerType.REGULAR, 499));
        assertRate("0.05", new Customer("Ada", CustomerType.REGULAR, 500));
    }

    @Test
    void goldLoyaltyStartsAtTwoThousandPoints() {
        assertRate("0.05", new Customer("Ada", CustomerType.REGULAR, 1999));
        assertRate("0.15", new Customer("Ada", CustomerType.REGULAR, 2000));
    }

    @Test
    void employeesGetTwentyPercent() {
        assertRate("0.20", new Customer("Eve", CustomerType.EMPLOYEE, 0));
    }

    private void assertRate(String expected, Customer customer) {
        assertEquals(0, new BigDecimal(expected).compareTo(policy.rateFor(customer)));
    }
}
# pricing

Small pricing library for the web shop: turns an order into a quote (subtotal, discount, tax, total) and renders
a plain-text receipt.

## Discounts

The discount rate for a customer is decided in one place, `DiscountPolicy.rateFor`:

| Customer                      | Rate |
|-------------------------------|------|
| Employee                      | 20%  |
| Loyalty points >= 2000        | 15%  |
| Loyalty points >= 500         | 5%   |
| Everyone else                 | 0%   |

All money is `BigDecimal` with two decimals, rounded half up (see `Money`).

## Running the tests

The project has no build tool. Put the JUnit 5 console launcher at `lib/junit-platform-console-standalone.jar`,
then run

    java tools/RunTests.java

It compiles everything under `src/` into `build/` and runs every test.
